const { ForbiddenException } = require('@nestjs/common');

// Assuming we have some role definitions in an object called 'ROLES'
const ROLES = {
  ADMIN: ['manage-all'],
  EDITOR: ['edit-content', 'view-articles'],
  USER: [],
};

/**
 * This function checks if the current user has the specified permission.
 *
 * @param {string} permission - The name of the permission to check for.
 * @returns {boolean} True if the user has the permission, false otherwise.
 */
function canPerformPermission(permission) {
  return ROLES.includes(permission);
}

/**
 * Guards that restrict access based on user roles.
 *
 * @param {*} next - Function to call when access is granted.
 * @throws {ForbiddenException} If the user does not have sufficient permissions.
 */
async function checkRole(next) {
  const token = req.headers['authorization'];
  // Assume `req` contains a decoded JWT or similar authentication mechanism

  try {
    // Check if the token is valid (for demonstration purposes)
    // In a real scenario, you would validate the token against your auth backend
    const isValidToken = true;

    if (!isValidToken) {
      throw new ForbiddenException('Invalid token');
    }

    // Extracting the username from the token
    const userId = extractUserIdFromJWT(token);

    // Fetching user role from database
    const userRole = await getUserRole(userId);

    // Checking if the user has the required role
    if (!canPerformPermission(userRole)) {
      throw new ForbiddenException('Insufficient permissions');
    }

    // Access granted, proceed with the next middleware/endpoint
    return next();
  } catch (err) {
    throw err;
  }
}

module.exports = {
  canPerformPermission,
  checkRole,
};
```
